<?php
declare(strict_types=1); namespace App\Http\Controllers\Personnel;
use App\Http\Controllers\Controller; use App\Http\Requests\Personnel\{ConfirmPersonnelImportRequest,UploadPersonnelImportRequest}; use App\Models\PersonnelImportBatch; use App\Services\Personnel\PersonnelImportService; use Illuminate\Http\{RedirectResponse,Response}; use Illuminate\View\View;
class PersonnelImportController extends Controller {public function __construct(private PersonnelImportService $service){}public function form():View{return view('personnel.import.form',['title'=>'Import Data Personalia']);}public function preview(UploadPersonnelImportRequest $r):RedirectResponse{$b=$this->service->preview($r->file('file'),$r->validated('duplicate_strategy'),$r->user());return redirect()->route('personnel.import.result',$b)->with('status','File berhasil dibaca. Silakan periksa pratinjau.');}public function confirm(ConfirmPersonnelImportRequest $r):RedirectResponse{$b=PersonnelImportBatch::findOrFail($r->validated('batch_id'));$this->service->confirm($b,$r->user());return redirect()->route('personnel.import.result',$b)->with('status','Import data personalia berhasil diselesaikan.');}public function result(PersonnelImportBatch $batch):View{abort_unless($batch->user_id===request()->user()->id||request()->user()->hasRole('super-admin'),403);return view('personnel.import.result',['title'=>'Hasil Import','batch'=>$batch,'rows'=>$batch->rows()->when(request('status'),fn($q,$s)=>$q->where('status',$s))->paginate(100)->withQueryString()]);}public function errors(PersonnelImportBatch $batch):Response{$csv="Nomor Baris,Nama,Status,Pesan Kesalahan\n";foreach($batch->rows()->whereIn('status',['invalid','warning'])->get() as $r)$csv.=implode(',',[(int)$r->row_number,'"'.str_replace('"','""',$r->normalized_data['full_name']??'').'"',$r->status,'"'.implode('; ',$r->messages??[]).'"'])."\n";return response($csv)->header('Content-Type','text/csv')->header('Content-Disposition','attachment; filename="laporan-error-personalia.csv"');}}
